int binarySearch(int arr[], int n, int target) {
    int low = 0, high = n - 1;

    while (low <= high) {
        int mid = low + (high - low) / 2;

        if (arr[mid] == target) {
            return mid;
            /* Found! */
        } else if (arr[mid] < target) {
            low = mid + 1;
            /* Search right half */
        } else {
            high = mid - 1;
            /* Search left half */
        }
    }
    return -1;
    /* Not found */
}

int main() {
    int arr[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    int n = sizeof(arr) / sizeof(arr[0]);
    printf("%d\n", binarySearch(arr, n, 23));
    /* 5 */
    printf("%d\n", binarySearch(arr, n, 10));
    /* -1 */
    return 0;
}

